-- 364: Original BrillaPrep WASSCE Core Mathematics Paper 2 theory practice paper (2024 format).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_364_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_364_guard;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM past_papers p WHERE p.id = 'pp_wassce_math_2024_2' AND NOT (p.id IS 'pp_wassce_math_2024_2' AND p.exam_type_id IS 'exam_wassce' AND p.subject_id IS 'subj_wassce_core_math' AND p.paper_type_id IS 'paper_wassce_2' AND p.year IS '2024' AND p.month IS 'May-June' AND p.series IS 'WASSCE' AND p.title IS 'Core Mathematics Paper 2 (2024)' AND p.description IS 'WASSCE Core Mathematics theory practice: compulsory Section A and Section B structured questions.' AND p.total_questions IS '10' AND p.total_marks IS '115' AND p.time_allowed IS '150' AND p.instructions IS 'Answer ALL the questions in Section A and FOUR questions from Section B.' AND p.is_complete IS '1' AND p.is_premium IS '0' AND p.source_url IS NULL)) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_001' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'A trader buys goods worth GH₵4,500.00 and sells them at a profit of 12%.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00. (b) 540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25). (c) Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.' AND q.explanation IS '(a) Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00. (b) 540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25). (c) Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.' AND q.difficulty IS 'medium' AND q.points IS '8' AND q.marks IS '8' AND q.time_limit IS NULL AND q.question_number IS '1' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_001' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_001_a' AND NOT (sp.question_id IS 'q_math_2024_2_001' AND sp.part_label IS 'a' AND sp.part_text IS 'Calculate the selling price of the goods.' AND sp.marks IS 3 AND sp.correct_answer IS 'Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_001_b' AND NOT (sp.question_id IS 'q_math_2024_2_001' AND sp.part_label IS 'b' AND sp.part_text IS 'Express the profit as a fraction of the cost price in its lowest terms.' AND sp.marks IS 2 AND sp.correct_answer IS '540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_001_c' AND NOT (sp.question_id IS 'q_math_2024_2_001' AND sp.part_label IS 'c' AND sp.part_text IS 'If the trader had instead made a loss of 8%, find what the selling price would have been.' AND sp.marks IS 3 AND sp.correct_answer IS 'Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_002' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'Consider the equations and formula given below.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 3x = 18, so x = 6. (b) r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length. (c) Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.' AND q.explanation IS '(a) 3x = 18, so x = 6. (b) r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length. (c) Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.' AND q.difficulty IS 'medium' AND q.points IS '8' AND q.marks IS '8' AND q.time_limit IS NULL AND q.question_number IS '2' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_002' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_002_a' AND NOT (sp.question_id IS 'q_math_2024_2_002' AND sp.part_label IS 'a' AND sp.part_text IS 'Solve the equation 3x − 7 = 11.' AND sp.marks IS 2 AND sp.correct_answer IS '3x = 18, so x = 6.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_002_b' AND NOT (sp.question_id IS 'q_math_2024_2_002' AND sp.part_label IS 'b' AND sp.part_text IS 'Make r the subject of the formula V = πr²h.' AND sp.marks IS 3 AND sp.correct_answer IS 'r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_002_c' AND NOT (sp.question_id IS 'q_math_2024_2_002' AND sp.part_label IS 'c' AND sp.part_text IS 'Solve the simultaneous equations 2x + y = 7 and x − y = 2.' AND sp.marks IS 3 AND sp.correct_answer IS 'Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_003' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'In triangle ABC, the interior angles are 2x°, 3x° and 4x°.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20. (b) 4x = 80°. (c) Acute, because all three angles (40°, 60°, 80°) are less than 90°.' AND q.explanation IS '(a) 2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20. (b) 4x = 80°. (c) Acute, because all three angles (40°, 60°, 80°) are less than 90°.' AND q.difficulty IS 'medium' AND q.points IS '8' AND q.marks IS '8' AND q.time_limit IS NULL AND q.question_number IS '3' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_003' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_003_a' AND NOT (sp.question_id IS 'q_math_2024_2_003' AND sp.part_label IS 'a' AND sp.part_text IS 'Find the value of x.' AND sp.marks IS 3 AND sp.correct_answer IS '2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_003_b' AND NOT (sp.question_id IS 'q_math_2024_2_003' AND sp.part_label IS 'b' AND sp.part_text IS 'State the size of the largest angle of the triangle.' AND sp.marks IS 2 AND sp.correct_answer IS '4x = 80°.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_003_c' AND NOT (sp.question_id IS 'q_math_2024_2_003' AND sp.part_label IS 'c' AND sp.part_text IS 'State, with a reason, whether triangle ABC is acute, right-angled or obtuse.' AND sp.marks IS 3 AND sp.correct_answer IS 'Acute, because all three angles (40°, 60°, 80°) are less than 90°.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_004' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'The numbers of goals scored by a football team in ten matches are: 2, 0, 3, 1, 2, 4, 2, 1, 3, 2.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 2 (it occurs four times, more than any other value). (b) Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2. (c) Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.' AND q.explanation IS '(a) 2 (it occurs four times, more than any other value). (b) Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2. (c) Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.' AND q.difficulty IS 'medium' AND q.points IS '8' AND q.marks IS '8' AND q.time_limit IS NULL AND q.question_number IS '4' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_004' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_004_a' AND NOT (sp.question_id IS 'q_math_2024_2_004' AND sp.part_label IS 'a' AND sp.part_text IS 'Write down the modal number of goals.' AND sp.marks IS 2 AND sp.correct_answer IS '2 (it occurs four times, more than any other value).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_004_b' AND NOT (sp.question_id IS 'q_math_2024_2_004' AND sp.part_label IS 'b' AND sp.part_text IS 'Find the median number of goals.' AND sp.marks IS 3 AND sp.correct_answer IS 'Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_004_c' AND NOT (sp.question_id IS 'q_math_2024_2_004' AND sp.part_label IS 'c' AND sp.part_text IS 'Calculate the mean number of goals per match.' AND sp.marks IS 3 AND sp.correct_answer IS 'Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_005' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'A cylindrical water tank has radius 7 cm and height 10 cm.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) V = πr²h = π × 7² × 10 = 490π cm³. (b) V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³. (c) Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².' AND q.explanation IS '(a) V = πr²h = π × 7² × 10 = 490π cm³. (b) V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³. (c) Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².' AND q.difficulty IS 'medium' AND q.points IS '8' AND q.marks IS '8' AND q.time_limit IS NULL AND q.question_number IS '5' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_005' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_005_a' AND NOT (sp.question_id IS 'q_math_2024_2_005' AND sp.part_label IS 'a' AND sp.part_text IS 'Write down an expression for the volume of the tank in terms of π.' AND sp.marks IS 3 AND sp.correct_answer IS 'V = πr²h = π × 7² × 10 = 490π cm³.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_005_b' AND NOT (sp.question_id IS 'q_math_2024_2_005' AND sp.part_label IS 'b' AND sp.part_text IS 'Taking π = 22/7, calculate the volume of the tank.' AND sp.marks IS 3 AND sp.correct_answer IS 'V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_005_c' AND NOT (sp.question_id IS 'q_math_2024_2_005' AND sp.part_label IS 'c' AND sp.part_text IS 'Taking π = 22/7, calculate the curved surface area of the tank.' AND sp.marks IS 2 AND sp.correct_answer IS 'Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_006' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'An amount of GH₵9,600.00 is shared among Ama, Kofi and Esi in the ratio 5 : 3 : 4 respectively.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200. (b) Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%. (c) Half of GH₵3,200 = GH₵1,600 saved.' AND q.explanation IS '(a) Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200. (b) Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%. (c) Half of GH₵3,200 = GH₵1,600 saved.' AND q.difficulty IS 'medium' AND q.points IS '15' AND q.marks IS '15' AND q.time_limit IS NULL AND q.question_number IS '6' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_006' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_006_a' AND NOT (sp.question_id IS 'q_math_2024_2_006' AND sp.part_label IS 'a' AND sp.part_text IS 'Calculate how much each person receives.' AND sp.marks IS 6 AND sp.correct_answer IS 'Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_006_b' AND NOT (sp.question_id IS 'q_math_2024_2_006' AND sp.part_label IS 'b' AND sp.part_text IS 'Express Ama''s share as a percentage of the total amount, giving your answer to one decimal place.' AND sp.marks IS 4 AND sp.correct_answer IS 'Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_006_c' AND NOT (sp.question_id IS 'q_math_2024_2_006' AND sp.part_label IS 'c' AND sp.part_text IS 'Esi saves half of her share and spends the rest. Calculate how much Esi saves.' AND sp.marks IS 5 AND sp.correct_answer IS 'Half of GH₵3,200 = GH₵1,600 saved.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_007' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'Consider the quadratic function y = x² − 5x + 6.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) (x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6. (b) (x − 2)(x − 3) = 0, so x = 2 or x = 3. (c) The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.' AND q.explanation IS '(a) (x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6. (b) (x − 2)(x − 3) = 0, so x = 2 or x = 3. (c) The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.' AND q.difficulty IS 'medium' AND q.points IS '15' AND q.marks IS '15' AND q.time_limit IS NULL AND q.question_number IS '7' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_007' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_007_a' AND NOT (sp.question_id IS 'q_math_2024_2_007' AND sp.part_label IS 'a' AND sp.part_text IS 'Factorise x² − 5x + 6.' AND sp.marks IS 4 AND sp.correct_answer IS '(x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_007_b' AND NOT (sp.question_id IS 'q_math_2024_2_007' AND sp.part_label IS 'b' AND sp.part_text IS 'Hence, or otherwise, solve the equation x² − 5x + 6 = 0.' AND sp.marks IS 5 AND sp.correct_answer IS '(x − 2)(x − 3) = 0, so x = 2 or x = 3.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_007_c' AND NOT (sp.question_id IS 'q_math_2024_2_007' AND sp.part_label IS 'c' AND sp.part_text IS 'Find the minimum value of y = x² − 5x + 6 and the value of x at which it occurs.' AND sp.marks IS 6 AND sp.correct_answer IS 'The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_008' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'From a point P on level ground, 30 m from the foot of a vertical mast, the angle of elevation of the top of the mast is 35°.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P. (b) tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m. (c) Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.' AND q.explanation IS '(a) A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P. (b) tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m. (c) Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.' AND q.difficulty IS 'medium' AND q.points IS '15' AND q.marks IS '15' AND q.time_limit IS NULL AND q.question_number IS '8' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_008' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_008_a' AND NOT (sp.question_id IS 'q_math_2024_2_008' AND sp.part_label IS 'a' AND sp.part_text IS 'Illustrate the information in a labelled diagram.' AND sp.marks IS 4 AND sp.correct_answer IS 'A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_008_b' AND NOT (sp.question_id IS 'q_math_2024_2_008' AND sp.part_label IS 'b' AND sp.part_text IS 'Calculate the height of the mast, correct to one decimal place.' AND sp.marks IS 6 AND sp.correct_answer IS 'tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_008_c' AND NOT (sp.question_id IS 'q_math_2024_2_008' AND sp.part_label IS 'c' AND sp.part_text IS 'Calculate the angle of elevation of the top of the mast from a point halfway between P and the foot of the mast, correct to the nearest degree.' AND sp.marks IS 5 AND sp.correct_answer IS 'Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_009' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'A bag contains 5 red balls and 3 blue balls. Two balls are drawn at random, one after the other, without replacement.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 5 red out of 8 balls, so P(first red) = 5/8. (b) P(both red) = 5/8 × 4/7 = 20/56 = 5/14. (c) P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.' AND q.explanation IS '(a) 5 red out of 8 balls, so P(first red) = 5/8. (b) P(both red) = 5/8 × 4/7 = 20/56 = 5/14. (c) P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.' AND q.difficulty IS 'medium' AND q.points IS '15' AND q.marks IS '15' AND q.time_limit IS NULL AND q.question_number IS '9' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_009' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_009_a' AND NOT (sp.question_id IS 'q_math_2024_2_009' AND sp.part_label IS 'a' AND sp.part_text IS 'Find the probability that the first ball drawn is red.' AND sp.marks IS 3 AND sp.correct_answer IS '5 red out of 8 balls, so P(first red) = 5/8.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_009_b' AND NOT (sp.question_id IS 'q_math_2024_2_009' AND sp.part_label IS 'b' AND sp.part_text IS 'Find the probability that both balls drawn are red.' AND sp.marks IS 6 AND sp.correct_answer IS 'P(both red) = 5/8 × 4/7 = 20/56 = 5/14.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_009_c' AND NOT (sp.question_id IS 'q_math_2024_2_009' AND sp.part_label IS 'c' AND sp.part_text IS 'Find the probability that the two balls drawn are of different colours.' AND sp.marks IS 6 AND sp.correct_answer IS 'P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.')) THEN 1 ELSE 0 END;
INSERT INTO _migration_364_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_math_2024_2_010' AND NOT (q.topic_id IS NULL AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_math_2024_2' AND q.question_text IS 'Consider the inequality 2x − 5 < 9, where x is a real number.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) 2x < 14, so x < 7. (b) An open circle at 7 with the line shaded to the left (all values less than 7). (c) The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.' AND q.explanation IS '(a) 2x < 14, so x < 7. (b) An open circle at 7 with the line shaded to the left (all values less than 7). (c) The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.' AND q.difficulty IS 'medium' AND q.points IS '15' AND q.marks IS '15' AND q.time_limit IS NULL AND q.question_number IS '10' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_math_2024_2_010' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_010_a' AND NOT (sp.question_id IS 'q_math_2024_2_010' AND sp.part_label IS 'a' AND sp.part_text IS 'Solve the inequality 2x − 5 < 9.' AND sp.marks IS 4 AND sp.correct_answer IS '2x < 14, so x < 7.')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_010_b' AND NOT (sp.question_id IS 'q_math_2024_2_010' AND sp.part_label IS 'b' AND sp.part_text IS 'Represent the solution on a number line.' AND sp.marks IS 5 AND sp.correct_answer IS 'An open circle at 7 with the line shaded to the left (all values less than 7).')) AND NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_math_2024_2_010_c' AND NOT (sp.question_id IS 'q_math_2024_2_010' AND sp.part_label IS 'c' AND sp.part_text IS 'Write down the largest integer that satisfies the inequality, and show that it does.' AND sp.marks IS 6 AND sp.correct_answer IS 'The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.')) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, series, title, description, total_questions, total_marks, time_allowed, instructions, is_complete, is_premium, source_url) VALUES ('pp_wassce_math_2024_2', 'exam_wassce', 'subj_wassce_core_math', 'paper_wassce_2', '2024', 'May-June', 'WASSCE', 'Core Mathematics Paper 2 (2024)', 'WASSCE Core Mathematics theory practice: compulsory Section A and Section B structured questions.', '10', '115', '150', 'Answer ALL the questions in Section A and FOUR questions from Section B.', '1', '0', NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_001', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'A trader buys goods worth GH₵4,500.00 and sells them at a profit of 12%.', 'structured', NULL, NULL, '(a) Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00. (b) 540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25). (c) Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.', '(a) Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00. (b) 540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25). (c) Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.', 'medium', '8', '8', NULL, '1', 'A', '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_002', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'Consider the equations and formula given below.', 'structured', NULL, NULL, '(a) 3x = 18, so x = 6. (b) r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length. (c) Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.', '(a) 3x = 18, so x = 6. (b) r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length. (c) Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.', 'medium', '8', '8', NULL, '2', 'A', '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_003', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'In triangle ABC, the interior angles are 2x°, 3x° and 4x°.', 'structured', NULL, NULL, '(a) 2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20. (b) 4x = 80°. (c) Acute, because all three angles (40°, 60°, 80°) are less than 90°.', '(a) 2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20. (b) 4x = 80°. (c) Acute, because all three angles (40°, 60°, 80°) are less than 90°.', 'medium', '8', '8', NULL, '3', 'A', '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_004', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'The numbers of goals scored by a football team in ten matches are: 2, 0, 3, 1, 2, 4, 2, 1, 3, 2.', 'structured', NULL, NULL, '(a) 2 (it occurs four times, more than any other value). (b) Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2. (c) Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.', '(a) 2 (it occurs four times, more than any other value). (b) Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2. (c) Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.', 'medium', '8', '8', NULL, '4', 'A', '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_005', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'A cylindrical water tank has radius 7 cm and height 10 cm.', 'structured', NULL, NULL, '(a) V = πr²h = π × 7² × 10 = 490π cm³. (b) V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³. (c) Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².', '(a) V = πr²h = π × 7² × 10 = 490π cm³. (b) V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³. (c) Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².', 'medium', '8', '8', NULL, '5', 'A', '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_006', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'An amount of GH₵9,600.00 is shared among Ama, Kofi and Esi in the ratio 5 : 3 : 4 respectively.', 'structured', NULL, NULL, '(a) Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200. (b) Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%. (c) Half of GH₵3,200 = GH₵1,600 saved.', '(a) Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200. (b) Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%. (c) Half of GH₵3,200 = GH₵1,600 saved.', 'medium', '15', '15', NULL, '6', 'B', '0', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_007', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'Consider the quadratic function y = x² − 5x + 6.', 'structured', NULL, NULL, '(a) (x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6. (b) (x − 2)(x − 3) = 0, so x = 2 or x = 3. (c) The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.', '(a) (x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6. (b) (x − 2)(x − 3) = 0, so x = 2 or x = 3. (c) The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.', 'medium', '15', '15', NULL, '7', 'B', '0', NULL, NULL, 'Solve', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_008', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'From a point P on level ground, 30 m from the foot of a vertical mast, the angle of elevation of the top of the mast is 35°.', 'structured', NULL, NULL, '(a) A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P. (b) tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m. (c) Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.', '(a) A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P. (b) tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m. (c) Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.', 'medium', '15', '15', NULL, '8', 'B', '0', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_009', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'A bag contains 5 red balls and 3 blue balls. Two balls are drawn at random, one after the other, without replacement.', 'structured', NULL, NULL, '(a) 5 red out of 8 balls, so P(first red) = 5/8. (b) P(both red) = 5/8 × 4/7 = 20/56 = 5/14. (c) P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.', '(a) 5 red out of 8 balls, so P(first red) = 5/8. (b) P(both red) = 5/8 × 4/7 = 20/56 = 5/14. (c) P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.', 'medium', '15', '15', NULL, '9', 'B', '0', NULL, NULL, 'Find', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_math_2024_2_010', NULL, 'subj_wassce_core_math', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_math_2024_2', 'Consider the inequality 2x − 5 < 9, where x is a real number.', 'structured', NULL, NULL, '(a) 2x < 14, so x < 7. (b) An open circle at 7 with the line shaded to the left (all values less than 7). (c) The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.', '(a) 2x < 14, so x < 7. (b) An open circle at 7 with the line shaded to the left (all values less than 7). (c) The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.', 'medium', '15', '15', NULL, '10', 'B', '0', NULL, NULL, 'Solve', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_001_a', 'q_math_2024_2_001', 'a', 'Calculate the selling price of the goods.', 3, 'Profit = 12% × 4,500 = GH₵540; selling price = 4,500 + 540 = GH₵5,040.00.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_001_b', 'q_math_2024_2_001', 'b', 'Express the profit as a fraction of the cost price in its lowest terms.', 2, '540/4,500 = 3/25 (equivalently, 12/100 reduces to 3/25).', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_001_c', 'q_math_2024_2_001', 'c', 'If the trader had instead made a loss of 8%, find what the selling price would have been.', 3, 'Loss = 8% × 4,500 = GH₵360; selling price = 4,500 − 360 = GH₵4,140.00.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_002_a', 'q_math_2024_2_002', 'a', 'Solve the equation 3x − 7 = 11.', 2, '3x = 18, so x = 6.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_002_b', 'q_math_2024_2_002', 'b', 'Make r the subject of the formula V = πr²h.', 3, 'r² = V/(πh), so r = √(V/(πh)), taking the positive root since r is a length.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_002_c', 'q_math_2024_2_002', 'c', 'Solve the simultaneous equations 2x + y = 7 and x − y = 2.', 3, 'Adding the equations: 3x = 9, so x = 3; then y = x − 2 = 1.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_003_a', 'q_math_2024_2_003', 'a', 'Find the value of x.', 3, '2x + 3x + 4x = 180 (angles in a triangle), so 9x = 180 and x = 20.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_003_b', 'q_math_2024_2_003', 'b', 'State the size of the largest angle of the triangle.', 2, '4x = 80°.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_003_c', 'q_math_2024_2_003', 'c', 'State, with a reason, whether triangle ABC is acute, right-angled or obtuse.', 3, 'Acute, because all three angles (40°, 60°, 80°) are less than 90°.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_004_a', 'q_math_2024_2_004', 'a', 'Write down the modal number of goals.', 2, '2 (it occurs four times, more than any other value).', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_004_b', 'q_math_2024_2_004', 'b', 'Find the median number of goals.', 3, 'Ordered: 0, 1, 1, 2, 2, 2, 2, 3, 3, 4; the median is the mean of the 5th and 6th values = 2.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_004_c', 'q_math_2024_2_004', 'c', 'Calculate the mean number of goals per match.', 3, 'Total = 20 goals over 10 matches, so the mean is 20 ÷ 10 = 2 goals per match.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_005_a', 'q_math_2024_2_005', 'a', 'Write down an expression for the volume of the tank in terms of π.', 3, 'V = πr²h = π × 7² × 10 = 490π cm³.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_005_b', 'q_math_2024_2_005', 'b', 'Taking π = 22/7, calculate the volume of the tank.', 3, 'V = (22/7) × 49 × 10 = 22 × 7 × 10 = 1,540 cm³.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_005_c', 'q_math_2024_2_005', 'c', 'Taking π = 22/7, calculate the curved surface area of the tank.', 2, 'Curved surface area = 2πrh = 2 × (22/7) × 7 × 10 = 440 cm².', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_006_a', 'q_math_2024_2_006', 'a', 'Calculate how much each person receives.', 6, 'Total parts = 12; one part = 9,600 ÷ 12 = GH₵800. Ama receives GH₵4,000, Kofi GH₵2,400 and Esi GH₵3,200.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_006_b', 'q_math_2024_2_006', 'b', 'Express Ama''s share as a percentage of the total amount, giving your answer to one decimal place.', 4, 'Ama''s share = 5/12 of GH₵9,600 = GH₵4,000; percentage = 4,000/9,600 × 100 = 41.7%.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_006_c', 'q_math_2024_2_006', 'c', 'Esi saves half of her share and spends the rest. Calculate how much Esi saves.', 5, 'Half of GH₵3,200 = GH₵1,600 saved.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_007_a', 'q_math_2024_2_007', 'a', 'Factorise x² − 5x + 6.', 4, '(x − 2)(x − 3), since −2 and −3 sum to −5 and multiply to 6.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_007_b', 'q_math_2024_2_007', 'b', 'Hence, or otherwise, solve the equation x² − 5x + 6 = 0.', 5, '(x − 2)(x − 3) = 0, so x = 2 or x = 3.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_007_c', 'q_math_2024_2_007', 'c', 'Find the minimum value of y = x² − 5x + 6 and the value of x at which it occurs.', 6, 'The minimum occurs at x = 5/2 = 2.5 (line of symmetry), giving y = (2.5)² − 5(2.5) + 6 = −0.25.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_008_a', 'q_math_2024_2_008', 'a', 'Illustrate the information in a labelled diagram.', 4, 'A right-angled triangle with horizontal leg 30 m from P to the foot of the mast, the mast vertical, and the 35° angle of elevation marked at P.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_008_b', 'q_math_2024_2_008', 'b', 'Calculate the height of the mast, correct to one decimal place.', 6, 'tan 35° = h/30, so h = 30 × tan 35° ≈ 30 × 0.7002 = 21.0 m.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_008_c', 'q_math_2024_2_008', 'c', 'Calculate the angle of elevation of the top of the mast from a point halfway between P and the foot of the mast, correct to the nearest degree.', 5, 'Distance = 15 m; tan θ = 21.0/15 = 1.40, so θ ≈ 54°.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_009_a', 'q_math_2024_2_009', 'a', 'Find the probability that the first ball drawn is red.', 3, '5 red out of 8 balls, so P(first red) = 5/8.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_009_b', 'q_math_2024_2_009', 'b', 'Find the probability that both balls drawn are red.', 6, 'P(both red) = 5/8 × 4/7 = 20/56 = 5/14.', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_009_c', 'q_math_2024_2_009', 'c', 'Find the probability that the two balls drawn are of different colours.', 6, 'P(both blue) = 3/8 × 2/7 = 3/28; P(different) = 1 − 5/14 − 3/28 = 1 − 10/28 − 3/28 = 15/28.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_010_a', 'q_math_2024_2_010', 'a', 'Solve the inequality 2x − 5 < 9.', 4, '2x < 14, so x < 7.', NULL, 'calculation', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_010_b', 'q_math_2024_2_010', 'b', 'Represent the solution on a number line.', 5, 'An open circle at 7 with the line shaded to the left (all values less than 7).', NULL, 'calculation', 2);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_math_2024_2_010_c', 'q_math_2024_2_010', 'c', 'Write down the largest integer that satisfies the inequality, and show that it does.', 6, 'The largest integer below 7 is 6; check: 2(6) − 5 = 7, which is less than 9, so 6 satisfies the inequality while 7 gives 9, which is not less than 9.', NULL, 'calculation', 3);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-paper2-theory-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://waecgh.org/', 0, 1 FROM questions WHERE id IN ('q_math_2024_2_001', 'q_math_2024_2_002', 'q_math_2024_2_003', 'q_math_2024_2_004', 'q_math_2024_2_005', 'q_math_2024_2_006', 'q_math_2024_2_007', 'q_math_2024_2_008', 'q_math_2024_2_009', 'q_math_2024_2_010');
DELETE FROM _migration_364_guard;
